'use strict';
const RIVALS_UI5={bind,help,performanceView};
function rivalDetail5(id){const r=state.rivals.find(r=>r.id===id);if(!r)return;const o=r.operations5,h=o.history.at(-1),t=o.review;show(`<span class="eyelabel">KONKURENČNÍ REPORT</span><h2>${esc(r.name)}</h2><p class="sub">${esc(RIVAL4[r.id]?.ceo||r.name)} · ${r.bankrupt?'Neaktivní firma':'Aktivní firma'}</p>${h?rows([['Tržby posledního týdne',money(h.revenue)],['Náklady včetně centrály a odběrů',money(h.cost)],['Provozní výsledek',money(h.profit)],['Investice zaplacené tento týden',money(h.investment)],['Změna hotovosti',money(h.cashChange)],['Hotovost po týdnu',money(h.cash)]]):empty('Zatím žádný uzavřený týden.')}<h3>Poslední strategické rozhodnutí</h3>${t?`<p>Týden ${t.week} · ${esc(t.chosen?.title||'Zachovat rezervu')}</p>${rows([['Hotovost před investicí',money(t.cash)],['Požadovaná rezerva',money(t.reserve)],['Cena zásahu',money(t.spent)],['Odhad týdenního přínosu',t.chosen?money(t.chosen.gain):'—'],['Jednoduchá návratnost',t.chosen?t.chosen.payback+' týdnů':'—']])}<h3>Další posuzované možnosti</h3>${t.alternatives.map(c=>`<p class="sub"><strong>${esc(c.title)}</strong> · ${money(c.cost)}, odhad +${money(c.gain)}/týden, ${c.payback} týdnů.<br>${esc(c.reason)}${c.allowed?' · nižší priorita nebo přínos na investici':''}</p>`).join('')||empty('Žádná další přínosná možnost.')}`:empty('První rozhodnutí teprve přijde.')}<h3>Historie kroků vedení</h3>${r.business.decisions.map(d=>`<p class="sub"><strong>Týden ${d.week} · ${esc(d.text)}</strong><br>${esc(d.detail)}</p>`).join('')||empty('Zatím bez rozhodnutí.')}<h3>Výsledky firmy</h3><div class="table-scroll"><table class="data"><thead><tr><th>Týden</th><th>Tržby</th><th>Výsledek</th><th>Investice</th><th>Hotovost</th></tr></thead><tbody>${o.history.slice(-13).map(q=>`<tr><td>${q.week}</td><td>${money(q.revenue)}</td><td>${money(q.profit)}</td><td>${money(q.investment)}</td><td>${money(q.cash)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Odhad přínosu používá současný trh; další výsledek může změnit konkurence a ekonomika. Investice snižují hotovost odděleně od provozního výsledku. Velkoobchodní odběry soupeřů používají souhrnný náklad. Placená prověrka zavede pro konkrétní kavárny jmenné smlouvy a fyzické placené šarže od data evidence. Historické zásoby se nedoplňují.</p><button class="primary" id="rivalBranches5">Otevřít report kaváren soupeřů</button>`);el('rivalBranches5').onclick=()=>{el('modal').close();reportKind5='rivalstores';goto('performance')};}
rivalsView=function(){const offers=UI3.rivalsView().split('<div class="section-header"><h2>Tvůj trh a soupeři</h2></div>')[0];return `<p class="intro">Soupeři řídí každou kavárnu podle její ceny, týmu, kapacity a nákladů. Napřed řeší ztráty nebo neobsloužené hosty; další investice potřebuje provozní rezervu a odhad návratnosti do 52 týdnů.</p><div class="cards">${state.rivals.map(r=>{const o=r.operations5,h=o.history.at(-1);return `<section class="card"><div class="card-head"><h2>${esc(r.name)}</h2><span class="badge">${r.acquired?'Převzata':r.bankrupt?'Bankrot':RIVAL4[r.id]?.title||'Aktivní'}</span></div><p class="sub">${esc(RIVAL4[r.id]?.ceo||r.name)} · CEO</p>${rows([['Hotovost',money(r.cash)],['Pobočky',r.stores.length],['Poslední provozní výsledek',h?money(h.profit):'—'],['Poslední tržby',h?money(h.revenue):'—'],['Velkoobchodní odběratelé',r.business.accounts+' / '+r.business.accountCapacity],['Pověst',number(r.reputation,1)+' / 100'],['Další pravidelné rozhodnutí','Týden '+r.business.expansionDue],['Poslední krok',esc(r.business.decisions[0]?.text||'Analýza trhu')]])}<div class="actions"><button class="soft" data-rival-report5="${r.id}">Otevřít report firmy</button><button class="primary" data-acquire="${r.id}" ${r.bankrupt||state.cash<rivalValuation(r)?'disabled':''}>Převzít · ${money(rivalValuation(r))}</button></div><details><summary>Vlastní kavárny · ceny a poslední výsledky</summary><div class="table-scroll"><table class="data"><thead><tr><th>Adresa</th><th>Cena</th><th>Tým</th><th>Výsledek</th><th>Neobsloužení</th></tr></thead><tbody>${o.branches.map(b=>`<tr><td><button class="quiet" data-jump-location="${b.id}">${esc(loc(b.id).city)} · ${esc(loc(b.id).name)} ↗</button></td><td>${money(round(loc(b.id).ideal*b.price))}</td><td>${b.staff}</td><td>${b.last?money(b.last.profit):'—'}</td><td>${b.last?number(b.last.lost):'—'}</td></tr>`).join('')}</tbody></table></div></details></section>`}).join('')}</div>${state.empire.partnership?`<section class="card" style="margin-top:24px"><h3>Nabídka obchodního partnerství</h3><p>${esc(state.rivals.find(r=>r.id===state.empire.partnership.rival)?.name)} chce ${state.empire.partnership.kg} kg týdně za ${money(state.empire.partnership.price)}/kg na 12 týdnů. Platí do týdne ${state.empire.partnership.due}; potřebuješ volného obchodníka.</p><div class="actions"><button class="primary" id="partnership4">Přijmout partnerství</button><button class="soft" id="declinePartnership4">Odmítnout</button></div></section>`:''}<div style="margin-top:24px">${offers}</div><p class="sub">Při akvizici převezmeš aktuální místní ceny, baristy a kvalitu nabídky. Potom kavárny spravuje tvůj provozní model s fyzickými zásobami. Dostupnost adres najdeš v Města & expanze.</p>`;};
performanceView=function(){return RIVALS_UI5.performanceView().replace('Soupeři používají agregovaný provozní model. Jejich zisk a hotovost jsou skutečné výsledky simulace; samostatné tržby nejsou dostupné.','Soupeři mají vlastní ceny a baristy. Pobočky platí kávu, mzdy, nájem a provoz; skutečné obsloužené návštěvy omezí kapacita. Výsledek firmy navíc zahrnuje obchod, centrálu a úroky; investice snižují hotovost zvlášť. Jejich šarže a individuální fronty se nesimulují.');};
bind=function(){RIVALS_UI5.bind();on('[data-rival-report5]',button=>rivalDetail5(button.dataset.rivalReport5))};
help=function(){RIVALS_UI5.help();const p=document.createElement('p');p.textContent='Edice 05.10: soupeři mají vlastní místní ceny, kapacitu, baristy, stav vybavení a výsledky poboček. Porovnávají zásahy, expanzi a rezervu; v Konkurence & akvizice otevřeš jejich report včetně důvodů a dalších posuzovaných možností. Report firmy přidává kategorii Kavárny soupeřů a skutečné tržby konkurence. Investiční odhady nejsou zaručený budoucí výnos.';el('modalContent').append(p)};el('help').onclick=help;render();
